    def migrate(self) -> None:
        self.ensure_collection("cc_ObjAttDes")
        # 清理被 Go 重命名/删除的旧属性（幂等）
        for oid, pid in self.STALE_KEYS:
            self.db["cc_ObjAttDes"].delete_many({
                "bk_obj_id": oid,
                "bk_property_id": pid,
                "bk_supplier_account": BK_DEFAULT_OWNER_ID,
            })
        ts = get_timestamp()
        for idx, item in enumerate(self.ATTRIBUTES, start=1):
            data = {**item,
                "id": idx,
                "bk_supplier_account": BK_DEFAULT_OWNER_ID,
                "creator": BK_SYSTEM_OPERATOR,
                "create_time": ts,
                "last_time": ts,
            }
            self.upsert("cc_ObjAttDes", data, ["bk_obj_id", "bk_property_id", "bk_supplier_account"])


